window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-3a78e05e50e5ba76"]={"versions": [{"id": "FIG-3a78e05e50e5ba76", "releases": ["R2.1.20", "R3.0.7"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Klassifikation:</strong> AUTOSAR-Methodik- und Tool-Interaktionsdiagramm (Work-Product & Activity Flow).</li>\n<li><strong>Technischer Zweck:</strong> Spezifikation der Werkzeugkategorien und Artefaktübergänge in der AUTOSAR-Entwicklungsmethodik (Classic Platform R2.1/R3.0). Dargestellt wird die funktionale Abgrenzung von <strong>AUTOSAR Authoring Tools</strong> (Autorenwerkzeuge für Modellerstellung und -pflege) gegenüber dem <strong>AUTOSAR System Configuration Generator</strong> sowie die Integration modellbasierter Funktionsentwicklung (MBD) über bidirektionale Kopplungswerkzeuge.</li>\n</ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">#### Datenartefakte / Work Products</p>\n<ul class=\"fig-list\">\n<li><strong><code>Behavioral Model</code> (Format-agnostisch / Tool-spezifisch):</strong></li>\n<li>Repräsentiert das algorithmische Verhaltensmodell (z. B. MATLAB/Simulink, ASCET, Stateflow).</li>\n<li>Bildet die mathematische Implementierung der späteren <code>RunnableEntities</code> ab.</li>\n<li><strong><code>System Configuration Input : System</code> (<code>.XML</code> / ARXML):</strong></li>\n<li>Partielles/unvollständiges AUTOSAR-Systemmodell vor der Allokation.</li>\n<li>Enthält Software Component Descriptions (<code>SWC-D</code>), Datentypen, Port-Interfaces sowie Topologie- und Netzwerk-Grobskizzen (Vorbereitung für das spätere ECU- und Signal-Mapping).</li>\n<li><strong><code>System Configuration Description : System</code> (<code>.XML</code> / ARXML):</strong></li>\n<li>Vollständiges, konsolidiertes Systemmodell nach Ausführung des System-Konfigurationsschritts.</li>\n<li>Enthält verbindliche Zuweisungen: SW-C-Instanzen auf ECUs (<code>SwcToEcuMapping</code>), Signale auf PDU-Layouts (<code>SystemSignal</code> zu <code>I-PDU</code>) und Kommunikationszeitpläne (Schedule Tables).</li>\n</ul>\n<p class=\"fig-p\">#### Werkzeuge & Transformationsprozesse</p>\n<ul class=\"fig-list\">\n<li><strong><code>Coupling Tool</code>:</strong></li>\n<li>Werkzeug zur Synchronisation und Brückenbildung zwischen MBD-Werkzeugen und AUTOSAR-ARXML-Metamodell.</li>\n<li><strong><code>Translation of Behavioral Model into SW-C Description</code>:</strong></li>\n<li>Extraktion von Ports, Interfaces, Parametern und Runnable-Strukturen aus dem Verhaltensmodell zur Generierung/Aktualisierung des <code>SWC-D</code>-Metamodells im <code>System Configuration Input</code>.</li>\n<li><strong><code>Translation of SW-C Description into Behavioral Model</code>:</strong></li>\n<li>Top-Down-Generierung von Modell-Hüllen (Model Skeletons/Harnesses) im MBD-Tool basierend auf vorgegebenen AUTOSAR-Port- und Interface-Definitionen.</li>\n<li><strong><code>AUTOSAR System Configuration Generator</code> / <code>Configure System</code>:</strong></li>\n<li>Regelbasierter Konfigurationsgenerator, der Softwarekomponenten, Topologie und Netzwerkbeschreibungen synthetisiert und das ECU-Mapping auflöst.</li>\n<li><strong>Scope <code>covered by authoring tools</code> (Rosa Containerblöcke):</strong></li>\n<li>Definiert den Verantwortungsbereich manueller oder geführter Autorenwerkzeuge: Erstellung/Modifikation des <code>System Configuration Input</code> und anschließende Nachbereitung/Inspektion der <code>System Configuration Description</code>.</li>\n</ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\">\n<li><strong>Round-Trip Engineering (Verhaltensmodell ↔ System-Input):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li><em>Top-Down:</em> Systemarchitekt definiert Ports/Interfaces im Authoring Tool (<code>System Configuration Input</code>) $\\rightarrow$ <code>Translation of SW-C Description into Behavioral Model</code> generiert Zielblöcke im <code>Behavioral Model</code>.</li>\n<li><em>Bottom-Up:</em> Funktionsentwickler passt Modellsignale/Parameter an $\\rightarrow$ <code>Translation of Behavioral Model into SW-C Description</code> aktualisiert die zugehörige Software-Component-Beschreibung im <code>System Configuration Input</code>.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>System-Synthese (<code>Configure System</code>):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Der <code>System Configuration Generator</code> liest das aggregierte <code>System Configuration Input</code>-XML ein.</li>\n<li>Deterministischer Transformationsschritt: Zuweisung von Komponenteninstanzen zu Steuergeräten, Bindung von Ports an netzwerkweite VFB-Kommunikationsbeziehungen und Signal-PDU-Synthese.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Erzeugung & Re-Authoring der Systemkonfiguration:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Ausgabe der konsolidierten <code>System Configuration Description</code>.</li>\n<li>Das Dokument fällt erneut in den Scope von Authoring Tools für Validierungs-, Kalibrierungs- und manuelle Anpassungsschritte vor dem nachgelagerten ECU-Extract (<code>EcuExtract</code>).</li>\n</ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>Vermeidung von Daten-Inkonsistenzen (MBD vs. ARXML):</strong></li>\n<li>Algorithmen dürfen nicht direkt ARXML modifizieren; die Brücke läuft zwingend über das <code>Coupling Tool</code>.</li>\n<li>Änderungen an Runnables, Trigger-Events oder Schnittstellentypen (z. B. <code>SenderReceiverInterface</code>, <code>ClientServerInterface</code>) im Modell erfordern eine erneute Übersetzung in das ARXML-Format, um Metamodell-Drift zu verhindern.</li>\n<li><strong>Artefakt-Rollen im Integrationsprozess:</strong></li>\n<li>Das <code>System Configuration Input</code> ist kein deploybares Artefakt für den BSW-Stack, sondern eine unvollständige Eingangsgröße.</li>\n<li>Erst die <code>System Configuration Description</code> liefert die formale Grundlage zur Extraktion von ECU-spezifischen Beschreibungen (<code>EcuExtract</code>), die anschließend als Input für RTE-Generatoren und BSW-Konfiguratoren dienen.</li>\n<li><strong>Konfigurationsgrenzen:</strong></li>\n<li>Der <code>System Configuration Generator</code> übernimmt automatisierte Allokationen; Feinjustierungen oder proprietäre Tool-Annotationen müssen über Authoring Tools im Einklang mit dem AUTOSAR-Schema (XSD) nachgepflegt werden, ohne generierte Bindeglieder (<code>FlatMap</code>, <code>Mapping</code>) zu zerstören.</li>\n</ul>"}, {"id": "FIG-0ef21487ba7e1cba", "releases": ["R3.1.5", "R3.2.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Klassifikation:</strong> AUTOSAR-Methodik- und Tool-Interaktionsdiagramm (Work-Product & Activity Flow).</li>\n<li><strong>Technischer Zweck:</strong> Spezifikation der Werkzeugkategorien und Artefaktübergänge in der AUTOSAR-Entwicklungsmethodik (Classic Platform R2.1/R3.0). Dargestellt wird die funktionale Abgrenzung von <strong>AUTOSAR Authoring Tools</strong> (Autorenwerkzeuge für Modellerstellung und -pflege) gegenüber dem <strong>AUTOSAR System Configuration Generator</strong> sowie die Integration modellbasierter Funktionsentwicklung (MBD) über bidirektionale Kopplungswerkzeuge.</li>\n</ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">#### Datenartefakte / Work Products</p>\n<ul class=\"fig-list\">\n<li><strong><code>Behavioral Model</code> (Format-agnostisch / Tool-spezifisch):</strong></li>\n<li>Repräsentiert das algorithmische Verhaltensmodell (z. B. MATLAB/Simulink, ASCET, Stateflow).</li>\n<li>Bildet die mathematische Implementierung der späteren <code>RunnableEntities</code> ab.</li>\n<li><strong><code>System Configuration Input : System</code> (<code>.XML</code> / ARXML):</strong></li>\n<li>Partielles/unvollständiges AUTOSAR-Systemmodell vor der Allokation.</li>\n<li>Enthält Software Component Descriptions (<code>SWC-D</code>), Datentypen, Port-Interfaces sowie Topologie- und Netzwerk-Grobskizzen (Vorbereitung für das spätere ECU- und Signal-Mapping).</li>\n<li><strong><code>System Configuration Description : System</code> (<code>.XML</code> / ARXML):</strong></li>\n<li>Vollständiges, konsolidiertes Systemmodell nach Ausführung des System-Konfigurationsschritts.</li>\n<li>Enthält verbindliche Zuweisungen: SW-C-Instanzen auf ECUs (<code>SwcToEcuMapping</code>), Signale auf PDU-Layouts (<code>SystemSignal</code> zu <code>I-PDU</code>) und Kommunikationszeitpläne (Schedule Tables).</li>\n</ul>\n<p class=\"fig-p\">#### Werkzeuge & Transformationsprozesse</p>\n<ul class=\"fig-list\">\n<li><strong><code>Coupling Tool</code>:</strong></li>\n<li>Werkzeug zur Synchronisation und Brückenbildung zwischen MBD-Werkzeugen und AUTOSAR-ARXML-Metamodell.</li>\n<li><strong><code>Translation of Behavioral Model into SW-C Description</code>:</strong></li>\n<li>Extraktion von Ports, Interfaces, Parametern und Runnable-Strukturen aus dem Verhaltensmodell zur Generierung/Aktualisierung des <code>SWC-D</code>-Metamodells im <code>System Configuration Input</code>.</li>\n<li><strong><code>Translation of SW-C Description into Behavioral Model</code>:</strong></li>\n<li>Top-Down-Generierung von Modell-Hüllen (Model Skeletons/Harnesses) im MBD-Tool basierend auf vorgegebenen AUTOSAR-Port- und Interface-Definitionen.</li>\n<li><strong><code>AUTOSAR System Configuration Generator</code> / <code>Configure System</code>:</strong></li>\n<li>Regelbasierter Konfigurationsgenerator, der Softwarekomponenten, Topologie und Netzwerkbeschreibungen synthetisiert und das ECU-Mapping auflöst.</li>\n<li><strong>Scope <code>covered by authoring tools</code> (Rosa Containerblöcke):</strong></li>\n<li>Definiert den Verantwortungsbereich manueller oder geführter Autorenwerkzeuge: Erstellung/Modifikation des <code>System Configuration Input</code> und anschließende Nachbereitung/Inspektion der <code>System Configuration Description</code>.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\">\n<li><strong>Round-Trip Engineering (Verhaltensmodell ↔ System-Input):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li><em>Top-Down:</em> Systemarchitekt definiert Ports/Interfaces im Authoring Tool (<code>System Configuration Input</code>) $\\rightarrow$ <code>Translation of SW-C Description into Behavioral Model</code> generiert Zielblöcke im <code>Behavioral Model</code>.</li>\n<li><em>Bottom-Up:</em> Funktionsentwickler passt Modellsignale/Parameter an $\\rightarrow$ <code>Translation of Behavioral Model into SW-C Description</code> aktualisiert die zugehörige Software-Component-Beschreibung im <code>System Configuration Input</code>.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>System-Synthese (<code>Configure System</code>):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Der <code>System Configuration Generator</code> liest das aggregierte <code>System Configuration Input</code>-XML ein.</li>\n<li>Deterministischer Transformationsschritt: Zuweisung von Komponenteninstanzen zu Steuergeräten, Bindung von Ports an netzwerkweite VFB-Kommunikationsbeziehungen und Signal-PDU-Synthese.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Erzeugung & Re-Authoring der Systemkonfiguration:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Ausgabe der konsolidierten <code>System Configuration Description</code>.</li>\n<li>Das Dokument fällt erneut in den Scope von Authoring Tools für Validierungs-, Kalibrierungs- und manuelle Anpassungsschritte vor dem nachgelagerten ECU-Extract (<code>EcuExtract</code>).</li>\n</ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>Vermeidung von Daten-Inkonsistenzen (MBD vs. ARXML):</strong></li>\n<li>Algorithmen dürfen nicht direkt ARXML modifizieren; die Brücke läuft zwingend über das <code>Coupling Tool</code>.</li>\n<li>Änderungen an Runnables, Trigger-Events oder Schnittstellentypen (z. B. <code>SenderReceiverInterface</code>, <code>ClientServerInterface</code>) im Modell erfordern eine erneute Übersetzung in das ARXML-Format, um Metamodell-Drift zu verhindern.</li>\n<li><strong>Artefakt-Rollen im Integrationsprozess:</strong></li>\n<li>Das <code>System Configuration Input</code> ist kein deploybares Artefakt für den BSW-Stack, sondern eine unvollständige Eingangsgröße.</li>\n<li>Erst die <code>System Configuration Description</code> liefert die formale Grundlage zur Extraktion von ECU-spezifischen Beschreibungen (<code>EcuExtract</code>), die anschließend als Input für RTE-Generatoren und BSW-Konfiguratoren dienen.</li>\n<li><strong>Konfigurationsgrenzen:</strong></li>\n<li>Der <code>System Configuration Generator</code> übernimmt automatisierte Allokationen; Feinjustierungen oder proprietäre Tool-Annotationen müssen über Authoring Tools im Einklang mit dem AUTOSAR-Schema (XSD) nachgepflegt werden, ohne generierte Bindeglieder (<code>FlatMap</code>, <code>Mapping</code>) zu zerstören.</li>\n</ul>"}], "trans": [{"from": "FIG-3a78e05e50e5ba76", "to": "FIG-0ef21487ba7e1cba", "fr": "R3.0.7", "tr": "R3.1.5", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
